   "state": "Washington",
   "name": "Facial recognition services law (ESSB 6280)",
   "status": "Unchanged",
   "year": "2020 (eff. 2021)",
   "does": "Agencies must give public notice and adopt an accountability report before using facial recognition, test it, allow independent accuracy testing, train users and have a person review significant decisions. A match can't be the sole basis for probable cause. Use must be disclosed to the defendant before trial. Real-time and ongoing surveillance needs a warrant, exigent circumstances or a court order; that part is not counted.",
   "who": "State and local agencies, including police",
   "rules": [
    "2",
    "4",
    "5",
    "7"
   ],
